package com.example

/**
 * Curated, 100% syllabus-aligned Flashcards for Agriculture & Food Technology (කෘෂි හා ආහාර තාක්ෂණය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category = 200 unique questions).
 */
object FlashcardBankAgriSetsPart2 {

  fun getAgriSet(s: Int, c: Int): CardContentTuple? {
    return when (s) {
      11 -> getSet11(c)
      12 -> getSet12(c)
      13 -> getSet13(c)
      14 -> getSet14(c)
      15 -> getSet15(c)
      16 -> getSet16(c)
      17 -> getSet17(c)
      18 -> getSet18(c)
      19 -> getSet19(c)
      20 -> getSet20(c)
      else -> null
    }
  }

